interface.definition:
a!localVariables(
  local!userid: #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1277768"(isActive: true()),
  local!user: if(
    a!isNotNullOrEmpty(local!userid),
    index(
      local!userid,
      #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48",
      {}
    ),
    {}
  ),

  #"SYSTEM_SYSRULES_formLayout_v2"(
    contents: {
      #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1277783"(
        userid: local!user,
        selectable: true(),
        selecteduserids: ri!selecteduserids
      )
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Submit",
          submit: true(),
          saveInto: {
            a!save(
              target: ri!button,
              value: #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085463"
            )
          },
          style: "SOLID",
          loadingIndicator: true()
        )
      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Cancel",
          submit: true(),
          saveInto: {
            a!save(
              target: ri!button,
              value: #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085469"
            )
          },
          validate: false(),
          style: "OUTLINE"
        )
      }
    )
  )
)
